// LogValue returns every setting as nested slog groups. Secrets show as
// [REDACTED] and URLs lose their password, so the whole Config is safe to log.
func (c Config) LogValue() slog.Value {
	return slog.GroupValue(
		slog.Group("app",
			slog.Duration("start_timeout", c.App.StartTimeout),
			slog.Duration("stop_timeout", c.App.StopTimeout),
			slog.Duration("health_timeout", c.App.HealthTimeout),
			slog.Duration("drain_delay", c.App.DrainDelay),
		),
		slog.Group("log",
			slog.String("level", c.Log.Level),
			slog.String("format", c.Log.Format),
			slog.String("wire", c.Log.Wire),
			slog.String("environment", c.Log.Environment),
			slog.String("service", c.Log.Service),
			slog.String("version", c.Log.Version),
		),
		slog.Group("tracing",
			slog.Bool("sdk_disabled", c.Tracing.SDKDisabled),
			slog.String("traces_exporter", c.Tracing.TracesExporter),
			slog.String("endpoint", c.Tracing.Endpoint),
			slog.String("traces_endpoint", c.Tracing.TracesEndpoint),
			slog.Float64("sample_ratio", c.Tracing.SampleRatio),
		),
		slog.Group("postgres",
			slog.String("host", c.Postgres.Host),
			slog.Int("port", c.Postgres.Port),
			slog.String("user", c.Postgres.User),
			slog.String("password", c.Postgres.Password.String()),
			slog.String("db", c.Postgres.DB),
			slog.String("sslmode", c.Postgres.SSLMode),
			slog.Int("max_open_conns", c.Postgres.MaxOpenConns),
			slog.Int("max_idle_conns", c.Postgres.MaxIdleConns),
			slog.Duration("conn_max_lifetime", c.Postgres.ConnMaxLifetime),
		),
		slog.Group("migrations",
			slog.Bool("enabled", c.Migrations.Enabled),
			slog.String("base_path", c.Migrations.BasePath),
			slog.Bool("validate", c.Migrations.Validate),
			slog.Bool("auto_fix_dirty", c.Migrations.AutoFixDirty),
			slog.Uint64("force_version", uint64(c.Migrations.ForceVersion)),
		),
		slog.Group("redis",
			slog.String("address", c.Redis.Address),
			slog.String("password", c.Redis.Password.String()),
			slog.Int("db", c.Redis.DB),
		),
		slog.Group("server",
			slog.String("host", c.Server.Config.Host),
			slog.Int("port", c.Server.Config.Port),
			slog.Duration("read_header_timeout", c.Server.Config.ReadHeaderTimeout),
			slog.Duration("read_timeout", c.Server.Config.ReadTimeout),
			slog.Duration("write_timeout", c.Server.Config.WriteTimeout),
			slog.Duration("idle_timeout", c.Server.Config.IdleTimeout),
			slog.Duration("shutdown_timeout", c.Server.Config.ShutdownTimeout),
			slog.String("allowed_origin", c.Server.AllowedOrigin),
		),
		slog.Group("core",
			slog.Group("auth",
				slog.Int64("refresh_token_lifetime", c.Core.Auth.RefreshTokenLifetime),
				slog.Int64("session_max_lifetime", c.Core.Auth.SessionMaxLifetime),
				slog.Int64("access_token_lifetime", c.Core.Auth.AccessTokenLifetime),
				slog.String("admin_jwt_secret", c.Core.Auth.AdminJWTSecret.String()),
			),
			slog.Group("encryption",
				slog.String("global_key", c.Core.Encryption.GlobalKey.String()),
				slog.String("global_key_version", c.Core.Encryption.GlobalKeyVersion),
			),
			slog.Group("integration",
				slog.Duration("reconcile_schedule_interval", c.Core.Integration.ReconcileScheduleInterval),
			),
			slog.String("environment", c.Core.Environment),
		),
	)
}

// String returns the redacted LogValue on one line, as path=value pairs.
func (c Config) String() string { return nanoconf.Format(c.LogValue()) }

// GoString keeps %#v as redacted as String.
func (c Config) GoString() string { return c.String() }
